        int n = Integer.parseInt(line.trim());
        int[][] dice = new int[n][6];

        for (int i = 0; i < n; i++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            StringTokenizer st = new StringTokenizer(line);
            for (int j = 0; j < 6; j++) {
                dice[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        int maxSum = 0;

        // Tenta cada uma das 6 faces do primeiro dado como face inferior
        for (int bottomFaceIdx = 0; bottomFaceIdx < 6; bottomFaceIdx++) {
            int currentSum = 0;
            int bottomVal = dice[0][bottomFaceIdx];
            int topVal = dice[0][OPPOSITE[bottomFaceIdx]];
            currentSum += getMaxSide(bottomVal, topVal);

            int prevTopVal = topVal;

            for (int i = 1; i < n; i++) {
                // Acha a face inferior do dado i, que deve ser igual a prevTopVal
                int bIdx = -1;
                for (int j = 0; j < 6; j++) {
                    if (dice[i][j] == prevTopVal) {
                        bIdx = j;
                        break;
                    }
                }
                int tIdx = OPPOSITE[bIdx];
                bottomVal = dice[i][bIdx];
                topVal = dice[i][tIdx];
                currentSum += getMaxSide(bottomVal, topVal);
                prevTopVal = topVal;
            }

            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }

        System.out.println(maxSum);
    }

    private static int getMaxSide(int v1, int v2) {
        if (v1 != 6 && v2 != 6) return 6;
        if (v1 != 5 && v2 != 5) return 5;
        return 4;
    }
}
